-- Fotos con licencia libre (Wikimedia Commons) para los productos del seed; los créditos están en
-- public/productos/creditos.json y la ficha los muestra. Solo rellena productos sin imagen propia.
update public.productos as p set imagen_url = v.archivo
from (values
  ('d0000000-0000-0000-0000-000000000001'::uuid, '/productos/d0000000-0000-0000-0000-000000000001.jpg'),
